import{_ as p,a0 as r,w as s,s as i,ao as l,I as a,x as e,a1 as u,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——怎样修改你的计算机名字 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——怎样修改你的计算机名字 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——怎样修改你的计算机名字 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——怎样修改你的计算机名字 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – How To Change Your Computer Name","title":"每日Ubuntu小技巧——怎样修改你的计算机名字","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – How To Change Your Computer Name.md","filePath":"[post].md"}'),d={name:"201311/Daily Ubuntu Tips – How To Change Your Computer Name.md"};function m(T,t,b,g,C,_){const n=r("Link");return s(),i("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧——怎样修改你的计算机名字" tabindex="-1">每日Ubuntu小技巧——怎样修改你的计算机名字 <a class="header-anchor" href="#每日ubuntu小技巧——怎样修改你的计算机名字" aria-label="Permalink to “每日Ubuntu小技巧——怎样修改你的计算机名字”">​</a></h1><p>本文又是一篇为Ubuntu新用户和新手准备的文章，将会指导你怎样在使用Ubuntu时轻松更改你的计算机名字，许多用户从来不会考虑在Ubuntu更改计算机名字或者主机名，那是他们最不用考虑担心的事情。</p><p>许多用户会使用安装Ubuntu过程中创建或设定的名字，但是对于想要知道怎么更改名字的新用户，可以继续接下来的学习。本文不是为Ubuntu专家所准备，是为那些刚刚开始使用Ubuntu的初学者用户。</p><p>那么，为什么你又想要更改你的计算机名字？如果除了想要学习怎样操作，你没有一个好的理由，那么就不要学了，反之，如果你有一个好的理由或者想要学习怎样操作，那么请继续。</p><p>按下 <strong>Ctrl - Alt - T</strong> 组合键，打开终端。 当终端打开，输入下列命令，使用gedit编辑hostname文件</p><pre><code>sudo gedit /etc/hostname
</code></pre><p>接下来，无论旧的计算机名字是什么，换一个新的吧。例如，如果你想要你的计算机名字为“RDOMNU”，先删除文件内容，输入 <strong>RDOMNU</strong>，然后保存文件。</p><p>然后，再输入下列命令来打开hosts文件</p><pre><code>sudo gedit /etc/hosts
</code></pre><p>更改第二行箭头标记位置的值，使它与你刚才输入的计算机名字相符，完成后保存文件。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/ubuntuhostnamechange.png" alt=""></p><p>就是这样！重启你的计算机，然后你的机器将会显示新的名字。这就是怎么改变Ubuntu机器的名字。</p><p>试一试吧！</p><hr>`,14)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-change-computer-name/"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-change-computer-name/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),u(n,{href:"https://blog.csdn.net/Vic___"},{default:o(()=>[...t[2]||(t[2]=[e("Vic___",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),u(n,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),u(n,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const h=p(d,[["render",m]]);export{w as __pageData,h as default};
